// Generated by main/CMakeLists.txt into the build directory from the build
// environment; it defines METRICS_PUSH_ENABLED and, when enabled, the
// credentials. No credential is ever committed or logged.
#include "metrics_credentials.h"
#include "mdns_service.h"
#include "voice_session.h"

static const char *TAG = "metrics";

// VictoriaMetrics adds both labels to every series in an import request. The
// job names this firmware, and the instance is the board's short name: the same
// last-three-MAC-bytes suffix that makes the mDNS hostname unique, with a
// stavvy- prefix instead of the hostname itself.
#define METRICS_URL_PREFIX                                                                                        \
    "http://metrics.home.stavros.io:38461/api/v1/import/prometheus?extra_label=job=stavvy&extra_label=instance="
#define METRICS_INSTANCE_PREFIX "stavvy-"
// Six hex characters and a terminator, matching mdns_service_get_mac_suffix().
#define METRICS_MAC_SUFFIX_BYTES 8

// The HTTP client's own logs carry the Authorization header at debug level. The
// default log level already compiles them out; this keeps them out of a debug
// build as well.
#define METRICS_HTTP_LOG_TAG "HTTP_CLIENT"

#if METRICS_PUSH_ENABLED
// Built once in metrics_init(), because the MAC suffix cannot change and the
// heartbeat should not format a URL every minute.
static char push_url[sizeof(METRICS_URL_PREFIX) + sizeof(METRICS_INSTANCE_PREFIX) + METRICS_MAC_SUFFIX_BYTES];

// A snapshot is about 1.5 KB. The body lives in BSS because the heartbeat task's
// stack is deliberately small and the body is only needed inside
// metrics_push().
#define METRICS_BODY_BYTES 2048

// Long enough for a slow DNS answer, short enough that a dead endpoint costs
// the minute's push rather than the minute's heartbeat. There is no retry.
#define METRICS_PUSH_TIMEOUT_MS 5000

// Written by several tasks, so every access is atomic. Only metrics_push()
// reads them, and a snapshot that races an increment only means one event is
// counted in the next minute's push.
static _Atomic uint32_t wake_words_total;
static _Atomic uint32_t key_presses_total;
static _Atomic uint32_t display_recoveries_total;
static _Atomic uint32_t push_failures_total;
static _Atomic uint32_t session_totals[METRICS_SESSION_OUTCOME_COUNT];
#endif

void metrics_count_wake_word(void)
{
#if METRICS_PUSH_ENABLED
    atomic_fetch_add(&wake_words_total, 1);
#endif
}

void metrics_count_session(metrics_session_outcome outcome)
{
#if METRICS_PUSH_ENABLED
    const unsigned index = (unsigned)outcome;
    if (index < METRICS_SESSION_OUTCOME_COUNT) {
        atomic_fetch_add(&session_totals[index], 1);
    }
#endif
}

void metrics_count_key_press(void)
{
#if METRICS_PUSH_ENABLED
    atomic_fetch_add(&key_presses_total, 1);
#endif
}

void metrics_count_display_recovery(void)
{
#if METRICS_PUSH_ENABLED
    atomic_fetch_add(&display_recoveries_total, 1);
#endif
}

// The Prometheus exposition format is line based, so each append is either
// whole lines or nothing. A body that does not fit is not sent at all, because
// a truncated line would break the whole import rather than one metric.
#if METRICS_PUSH_ENABLED
static bool append(char *body, size_t capacity, size_t *used, const char *format, ...)
{
    const size_t remaining = capacity - *used;
    if (remaining == 0) {
        return false;
    }

    va_list arguments;
    va_start(arguments, format);
    const int written = vsnprintf(body + *used, remaining, format, arguments);
    va_end(arguments);

    if (written < 0 || (size_t)written >= remaining) {
        return false;
    }
    *used += (size_t)written;
    return true;
}

static const char *reset_reason_label(esp_reset_reason_t reason)
{
    switch (reason) {
    case ESP_RST_UNKNOWN:
        return "unknown";
    case ESP_RST_POWERON:
        return "power_on";
    case ESP_RST_EXT:
        return "external_pin";
    case ESP_RST_SW:
        return "software";
    case ESP_RST_PANIC:
        return "panic";
    case ESP_RST_INT_WDT:
        return "interrupt_watchdog";
    case ESP_RST_TASK_WDT:
        return "task_watchdog";
    case ESP_RST_WDT:
        return "other_watchdog";
    case ESP_RST_DEEPSLEEP:
        return "deep_sleep";
    case ESP_RST_BROWNOUT:
        return "brownout";
    case ESP_RST_SDIO:
        return "sdio";
    case ESP_RST_USB:
        return "usb";
    case ESP_RST_JTAG:
        return "jtag";
    case ESP_RST_EFUSE:
        return "efuse_error";
    case ESP_RST_PWR_GLITCH:
        return "power_glitch";
    case ESP_RST_CPU_LOCKUP:
        return "cpu_lockup";
    }
    return "unknown";
}

static const char *session_outcome_label(metrics_session_outcome outcome)
{
    switch (outcome) {
    case METRICS_SESSION_OUTCOME_REPLY:
        return "reply";
    case METRICS_SESSION_OUTCOME_NO_SERVER:
        return "no_server";
    case METRICS_SESSION_OUTCOME_ERROR:
        return "error";
    case METRICS_SESSION_OUTCOME_TIMEOUT:
        return "timeout";
    case METRICS_SESSION_OUTCOME_DISCONNECTED:
        return "disconnected";
    case METRICS_SESSION_OUTCOME_COUNT:
        break;
    }
    return "error";
}

static bool format_metrics(char *body, size_t capacity, size_t *length, const board_power_status *power)
{
    *length = 0;

    if (!append(body, capacity, length,
                "# TYPE stavvy_uptime_seconds gauge\n"
                "stavvy_uptime_seconds %lu\n",
                (unsigned long)(esp_timer_get_time() / 1000000))) {
        return false;
    }

    if (!append(body, capacity, length,
                "# TYPE stavvy_heap_free_bytes gauge\n"
                "stavvy_heap_free_bytes %u\n"
                "# TYPE stavvy_heap_minimum_free_bytes gauge\n"
                "stavvy_heap_minimum_free_bytes %u\n"
                "# TYPE stavvy_heap_largest_free_block_bytes gauge\n"
                "stavvy_heap_largest_free_block_bytes %u\n",
                (unsigned)esp_get_free_heap_size(), (unsigned)esp_get_minimum_free_heap_size(),
                (unsigned)heap_caps_get_largest_free_block(MALLOC_CAP_DEFAULT))) {
        return false;
    }

    // While the station is not associated the value is meaningless, so the
    // series is left out rather than reported as zero.
    wifi_ap_record_t access_point;
    if (esp_wifi_sta_get_ap_info(&access_point) == ESP_OK) {
        if (!append(body, capacity, length,
                    "# TYPE stavvy_wifi_rssi_dbm gauge\n"
                    "stavvy_wifi_rssi_dbm %d\n",
                    access_point.rssi)) {
            return false;
        }
    }

    if (!append(body, capacity, length,
                "# TYPE stavvy_api_client_connected gauge\n"
                "stavvy_api_client_connected %d\n"
                "# TYPE stavvy_microphone_muted gauge\n"
                "stavvy_microphone_muted %d\n",
                esphome_api_client_connected() ? 1 : 0, voice_session_is_muted() ? 1 : 0)) {
        return false;
    }

    // The three power values come from the one AXP2101 read the heartbeat takes,
    // so they are either all present or all absent. A failed read is not a
    // reason to drop the rest of the snapshot.
    if (power != NULL) {
        const bool temperature_negative = power->temperature_tenths < 0;
        const int temperature_magnitude =
            temperature_negative ? -power->temperature_tenths : power->temperature_tenths;
        if (!append(body, capacity, length,
                    "# TYPE stavvy_battery_volts gauge\n"
                    "stavvy_battery_volts %u.%03u\n"
                    "# TYPE stavvy_system_volts gauge\n"
                    "stavvy_system_volts %u.%03u\n"
                    "# TYPE stavvy_pmic_temperature_celsius gauge\n"
                    "stavvy_pmic_temperature_celsius %s%d.%d\n",
                    power->battery_millivolts / 1000, (unsigned)(power->battery_millivolts % 1000),
                    power->system_millivolts / 1000, (unsigned)(power->system_millivolts % 1000),
                    temperature_negative ? "-" : "", temperature_magnitude / 10, temperature_magnitude % 10)) {
            return false;
        }
    }

    if (!append(body, capacity, length,
                "# TYPE stavvy_boot_info gauge\n"
                "stavvy_boot_info{reset_reason=\"%s\"} 1\n",
                reset_reason_label(esp_reset_reason()))) {
        return false;
    }

    if (!append(body, capacity, length,
                "# TYPE stavvy_wake_words_total counter\n"
                "stavvy_wake_words_total %lu\n"
                "# TYPE stavvy_sessions_total counter\n",
                (unsigned long)atomic_load(&wake_words_total))) {
        return false;
    }

    // Every label value is emitted even at zero, so the series exist from the
    // first push and a graph does not have a gap where an outcome has not
    // happened yet.
    for (int outcome = 0; outcome < METRICS_SESSION_OUTCOME_COUNT; outcome++) {
        if (!append(body, capacity, length, "stavvy_sessions_total{outcome=\"%s\"} %lu\n",
                    session_outcome_label((metrics_session_outcome)outcome),
                    (unsigned long)atomic_load(&session_totals[outcome]))) {
            return false;
        }
    }

    if (!append(body, capacity, length,
                "# TYPE stavvy_key_presses_total counter\n"
                "stavvy_key_presses_total %lu\n"
                "# TYPE stavvy_display_recoveries_total counter\n"
                "stavvy_display_recoveries_total %lu\n"
                "# TYPE stavvy_metrics_push_failures_total counter\n"
                "stavvy_metrics_push_failures_total %lu\n",
                (unsigned long)atomic_load(&key_presses_total),
                (unsigned long)atomic_load(&display_recoveries_total),
                (unsigned long)atomic_load(&push_failures_total))) {
        return false;
    }

    return true;
}
#endif

void metrics_init(void)
{
#if METRICS_PUSH_ENABLED
    char mac_suffix[METRICS_MAC_SUFFIX_BYTES];
    mdns_service_get_mac_suffix(mac_suffix, sizeof(mac_suffix));
    snprintf(push_url, sizeof(push_url), "%s%s%s", METRICS_URL_PREFIX, METRICS_INSTANCE_PREFIX, mac_suffix);
    // Keep the Authorization header that esp_http_client logs at debug level out
    // of the log even in a build whose default level is debug.
    esp_log_level_set(METRICS_HTTP_LOG_TAG, ESP_LOG_INFO);
    ESP_LOGI(TAG, "Metrics push enabled every heartbeat for instance=%s%s", METRICS_INSTANCE_PREFIX, mac_suffix);
#else
    ESP_LOGW(TAG, "Metrics push disabled: VM_USERNAME and VM_PASSWORD were empty when the build was configured");
#endif
}

void metrics_push(const board_power_status *power)
{
#if METRICS_PUSH_ENABLED
    // A session owns the Wi-Fi connection, the heap and the CPU while it
    // streams and plays; a push in the middle of one would only slow it down.
    if (!voice_session_is_idle()) {
        ESP_LOGD(TAG, "Skipping the metrics push while a session is running");
        return;
    }

    static char body[METRICS_BODY_BYTES];
    size_t length = 0;
    if (!format_metrics(body, sizeof(body), &length, power)) {
        ESP_LOGW(TAG, "The metrics snapshot did not fit in %d bytes, not pushing", METRICS_BODY_BYTES);
        atomic_fetch_add(&push_failures_total, 1);
        return;
    }

    const esp_http_client_config_t config = {
        .url = push_url,
        .username = METRICS_USERNAME,
        .password = METRICS_PASSWORD,
        .auth_type = HTTP_AUTH_TYPE_BASIC,
        .timeout_ms = METRICS_PUSH_TIMEOUT_MS,
        // The endpoint is a known host: following a redirect or retrying a
        // rejected Authorization header would send the credentials somewhere
        // else or send them again, neither of which this push should ever do.
        .disable_auto_redirect = true,
        .max_authorization_retries = -1,
        .keep_alive_enable = false,
    };
    esp_http_client_handle_t client = esp_http_client_init(&config);
    if (client == NULL) {
        ESP_LOGW(TAG, "Could not create the HTTP client for the metrics push");
        atomic_fetch_add(&push_failures_total, 1);
        return;
    }

    esp_err_t setup_result = esp_http_client_set_method(client, HTTP_METHOD_POST);
    if (setup_result == ESP_OK) {
        setup_result = esp_http_client_set_header(client, "Content-Type", "text/plain; version=0.0.4");
    }
    if (setup_result == ESP_OK) {
        setup_result = esp_http_client_set_post_field(client, body, (int)length);
    }
    if (setup_result != ESP_OK) {
        ESP_LOGW(TAG, "Could not prepare the metrics request (0x%x)", setup_result);
        esp_http_client_cleanup(client);
        atomic_fetch_add(&push_failures_total, 1);
        return;
    }

    const int64_t started_microseconds = esp_timer_get_time();
    const esp_err_t result = esp_http_client_perform(client);
    const int status = esp_http_client_get_status_code(client);
    esp_http_client_cleanup(client);

    const int64_t elapsed_milliseconds = (esp_timer_get_time() - started_microseconds) / 1000;
    if (result != ESP_OK || status < 200 || status >= 300) {
        // One warning per failed push, no retry and no queue: the next
        // heartbeat is the retry.
        ESP_LOGW(TAG, "Metrics push failed (0x%x, HTTP %d, %lld ms), retrying at the next heartbeat", result, status,
                 (long long)elapsed_milliseconds);
        atomic_fetch_add(&push_failures_total, 1);
        return;
    }

    ESP_LOGI(TAG, "Metrics pushed (HTTP %d, %u bytes, %lld ms)", status, (unsigned)length,
             (long long)elapsed_milliseconds);
#else
    (void)power;
#endif
}
